def V(code,inp=''): return RUN(code,inp)
SEL='def chon(a):\n    for i in range(len(a) - 1):\n        m = i\n        for j in range(i + 1, len(a)):\n            if a[j] < a[m]:\n                m = j\n        a[i], a[m] = a[m], a[i]\n    return a'
BUB='def noi_bot(a):\n    dem = 0\n    for i in range(len(a) - 1):\n        doi = False\n        for j in range(len(a) - 1 - i):\n            dem += 1\n            if a[j] > a[j + 1]:\n                a[j], a[j + 1] = a[j + 1], a[j]\n                doi = True\n        if not doi:\n            break\n    return dem'
INS='def chen(a):\n    for i in range(1, len(a)):\n        x = a[i]\n        j = i - 1\n        while j >= 0 and a[j] > x:\n            a[j + 1] = a[j]\n            j -= 1\n        a[j + 1] = x\n    return a'
