S.append(TB(c,B+' · 3','Đếm số phép so sánh của nổi bọt có dừng sớm',['Mảng','Số lượt chạy','Số so sánh','Giải thích'],[['[1, 2, 3, 4, 5, 6]','1','<b>5</b>','không đổi chỗ → dừng sau lượt 1'],['[6, 5, 4, 3, 2, 1]','5','<b>15</b>','xấu nhất: 5+4+3+2+1'],['[2, 1, 3, 4, 5, 6]','2','<b>9</b>','lượt 1: 5 (đổi 2,1); lượt 2: 4 (không đổi) → dừng'],['[1, 2, 3, 4, 6, 5]','2','<b>9</b>','lượt 1: 5 (đổi 6,5); lượt 2: 4 → dừng']],note=KEY('Đáp án: <b>5 15 9 9</b>. Tốt nhất O(n) khi đã sắp xếp (nhờ cờ dừng sớm); xấu nhất O(n²).')))
S.append(S2(c,B+' · 3','Kiểm chứng bằng chương trình',card('Số phép so sánh bốn mảng',P('Đây là câu trong đề: kết quả <b>5 15 9 9</b>.','Chú ý: phiên bản <b>không có cờ dừng sớm</b> luôn tốn n(n−1)/2 = 15 phép dù mảng đã sắp xếp.')),CODE('# dùng hàm noi_bot (có cờ dừng sớm)\nfor a in ([1,2,3,4,5,6], [6,5,4,3,2,1],\n          [2,1,3,4,5,6], [1,2,3,4,6,5]):\n    print(noi_bot(a), end=" ")',22)+R(BUB+'\nprint(noi_bot([1,2,3,4,5,6]), noi_bot([6,5,4,3,2,1]), noi_bot([2,1,3,4,5,6]), noi_bot([1,2,3,4,6,5]))','',26,'Kết quả')) )
S.append(S2(c,B+' · 4','Sắp xếp chèn (Insertion sort)',card('Như xếp bài trên tay',STEPS(['Phần đầu <b>a[0..i−1]</b> đã sắp xếp.','Lấy <b>x = a[i]</b>, dịch các phần tử <b>lớn hơn x</b> sang phải một bước.','Chèn x vào chỗ trống.'])+KEY('Tốt nhất O(n) (đã sắp xếp); xấu nhất O(n²) (ngược). <b>Ổn định</b> và rất nhanh với mảng gần sắp xếp.')),CODE(INS,20)+R(INS+'\nprint(chen([29, 10, 14, 37, 13]))','',24,'Kết quả')))
