S.append(S2(c,B+' · 5','Tính ổn định (stable)',card('Định nghĩa',P('Sắp xếp <b>ổn định</b>: hai phần tử có <b>khoá bằng nhau</b> giữ nguyên <b>thứ tự ban đầu</b>.','Quan trọng khi sắp xếp theo <b>nhiều tiêu chí lần lượt</b> (ví dụ: theo điểm, bằng điểm thì giữ thứ tự theo tên đã xếp trước).','Ổn định: <b>chèn, nổi bọt (với &gt;), trộn, sort() của Python, đếm phân phối</b>. Không ổn định: <b>chọn (đổi chỗ xa)</b>, nhanh, vun đống.')),CODE('a = [(2, "a"), (2, "b"), (1, "c")]\nb = a[:]\nfor i in range(len(b)):\n    m = i\n    for j in range(i + 1, len(b)):\n        if b[j][0] < b[m][0]:\n            m = j\n    b[i], b[m] = b[m], b[i]\nprint(b)\nc = sorted(a, key=lambda p: p[0])\nprint(c)',19)+R('a = [(2, "a"), (2, "b"), (1, "c")]\nb = a[:]\nfor i in range(len(b)):\n    m = i\n    for j in range(i + 1, len(b)):\n        if b[j][0] < b[m][0]:\n            m = j\n    b[i], b[m] = b[m], b[i]\nprint(b)\nc = sorted(a, key=lambda p: p[0])\nprint(c)','',22,'Chọn: (2,a) và (2,b) bị đảo; sorted: giữ thứ tự')))
S.append(S2(c,B+' · 5','Vì sao chọn mất ổn định?',card('Phân tích từng bước',P('[(2,a), (2,b), (1,c)]: lượt i = 0: nhỏ nhất là (1,c) ở vị trí 2; <b>đổi a[0] ↔ a[2]</b> → [(1,c), (2,b), (2,a)].','Phần tử (2,a) bị <b>đưa ra sau</b> (2,b): thứ tự tương đối của hai khoá 2 đã bị đảo.','Sắp xếp <b>chèn</b> chỉ dịch các phần tử <b>lớn hơn hẳn</b> (&gt;), nên giữ nguyên thứ tự khi bằng nhau.')),CODE('a = [(2, "a"), (2, "b"), (1, "c")]\nc = a[:]\nfor i in range(1, len(c)):\n    x = c[i]\n    j = i - 1\n    while j >= 0 and c[j][0] > x[0]:\n        c[j + 1] = c[j]\n        j -= 1\n    c[j + 1] = x\nprint(c)',20)+R('a = [(2, "a"), (2, "b"), (1, "c")]\nc = a[:]\nfor i in range(1, len(c)):\n    x = c[i]\n    j = i - 1\n    while j >= 0 and c[j][0] > x[0]:\n        c[j + 1] = c[j]\n        j -= 1\n    c[j + 1] = x\nprint(c)','',24,'Chèn: ổn định')+KEY('Đáp án đề: chọn → c, b, a; chèn → c, a, b.')))
S.append(TB(c,B+' · 5','So sánh ba thuật toán cơ bản',['','Chọn','Nổi bọt (dừng sớm)','Chèn'],[['Tốt nhất','O(n²)','<b>O(n)</b>','<b>O(n)</b>'],['Xấu nhất','O(n²)','O(n²)','O(n²)'],['So sánh (n = 6, xấu nhất)','15','15','15'],['Số lần đổi chỗ','≤ n − 1','đến n(n−1)/2','dịch ≈ n(n−1)/2'],['Ổn định','không','có','có'],['Bộ nhớ phụ','O(1)','O(1)','O(1)']],note=KEY('Cả ba đều <b>sắp xếp tại chỗ</b> (O(1) bộ nhớ). Với n = 10⁵: n² = 10¹⁰ → quá chậm; cần O(n log n).')))
S.append(S2(c,B+' · 6','Sắp xếp trộn (Merge sort): chia để trị',card('Ý tưởng',STEPS(['<b>Chia</b> mảng làm hai nửa.','<b>Sắp xếp</b> từng nửa (đệ quy).','<b>Trộn</b> hai nửa đã sắp xếp thành một (so sánh đầu hai dãy).'])+KEY('Chiều sâu <b>log₂ n</b>, mỗi tầng trộn <b>O(n)</b> → <b>O(n log n)</b> luôn luôn. Ổn định; bộ nhớ phụ O(n).')),CODE('def tron(a):\n    if len(a) <= 1:\n        return a\n    m = len(a) // 2\n    t, p = tron(a[:m]), tron(a[m:])\n    kq = []\n    while t and p:\n        nua = t if t[0] <= p[0] else p\n        kq.append(nua.pop(0))\n    return kq + t + p\nprint(tron([29, 10, 14, 37, 13, 5]))',20)+R('def tron(a):\n    if len(a) <= 1:\n        return a\n    m = len(a) // 2\n    t, p = tron(a[:m]), tron(a[m:])\n    kq = []\n    while t and p:\n        nua = t if t[0] <= p[0] else p\n        kq.append(nua.pop(0))\n    return kq + t + p\nprint(tron([29, 10, 14, 37, 13, 5]))','',24,'Kết quả')))
S.append(S2(c,B+' · 6','Sắp xếp đếm phân phối (Counting sort)',card('Khi giá trị nhỏ',P('Nếu giá trị nguyên nằm trong <b>[0, V]</b> và V không quá lớn: đếm số lần xuất hiện từng giá trị rồi <b>xuất ra theo thứ tự</b>.','Thời gian <b>O(n + V)</b> — nhanh hơn O(n log n) khi V nhỏ (ví dụ điểm 0..10, tuổi 0..120).')),CODE('a = [3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5]\nV = 9\ncnt = [0] * (V + 1)\nfor x in a:\n    cnt[x] += 1\nkq = []\nfor v in range(V + 1):\n    kq += [v] * cnt[v]\nprint(cnt)\nprint(kq)',20)+R('a = [3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5]\nV = 9\ncnt = [0] * (V + 1)\nfor x in a:\n    cnt[x] += 1\nkq = []\nfor v in range(V + 1):\n    kq += [v] * cnt[v]\nprint(cnt)\nprint(kq)','',22,'Kết quả')+KEY('Không dựa trên so sánh nên <b>vượt giới hạn n log n</b> của sắp xếp so sánh.')))
S.append(S2(c,B+' · 7','sort() và sorted() trong Python',card('Cách dùng chuyên nghiệp',P('<b>a.sort()</b>: sửa tại chỗ, trả <b>None</b>; <b>sorted(a)</b>: danh sách mới.','Thuật toán <b>Timsort</b>: <b>O(n log n)</b> xấu nhất, <b>O(n)</b> khi đã gần sắp xếp, <b>ổn định</b>.','<b>key</b>: hàm cho khoá; <b>reverse=True</b>: giảm dần.','Sắp xếp theo <b>nhiều tiêu chí</b>: key trả về <b>tuple</b>.')),CODE('hs = [("An", 8), ("Binh", 9), ("Chi", 8), ("Dung", 9)]\nprint(sorted(hs, key=lambda p: (-p[1], p[0])))\nprint(sorted(hs, key=lambda p: p[1], reverse=True))\nds = ["b2", "a10", "a2"]\nprint(sorted(ds))\nprint(sorted(ds, key=lambda s: (s[0], int(s[1:]))))',19)+R('hs = [("An", 8), ("Binh", 9), ("Chi", 8), ("Dung", 9)]\nprint(sorted(hs, key=lambda p: (-p[1], p[0])))\nprint(sorted(hs, key=lambda p: p[1], reverse=True))\nds = ["b2", "a10", "a2"]\nprint(sorted(ds))\nprint(sorted(ds, key=lambda s: (s[0], int(s[1:]))))','',20,'Kết quả')+KEY('Dòng 2: <b>reverse=True</b> vẫn giữ thứ tự ban đầu khi bằng điểm (An, Chi) vì ổn định.')))
S.append(S2(c,B+' · 7','Ứng dụng: sắp xếp rồi xử lí',card('Ba mẫu hay dùng',P('<b>Loại trùng</b>: sắp xếp rồi so sánh phần tử kề nhau.','<b>Trung vị</b>: phần tử giữa của dãy đã sắp xếp.','<b>Cặp gần nhất / hiệu nhỏ nhất</b>: chỉ cần xét <b>các cặp kề nhau</b> sau khi sắp xếp.')),CODE('a = [31, 4, 15, 9, 26, 5, 35]\nb = sorted(a)\nprint(b[len(b) // 2])\nprint(min(b[i + 1] - b[i] for i in range(len(b) - 1)))\nc = [3, 1, 3, 2, 1]\nprint(sum(1 for i in range(1, len(c)) if sorted(c)[i] != sorted(c)[i - 1]) + 1)',19)+R('a = [31, 4, 15, 9, 26, 5, 35]\nb = sorted(a)\nprint(b[len(b) // 2])\nprint(min(b[i + 1] - b[i] for i in range(len(b) - 1)))\nc = [3, 1, 3, 2, 1]\nprint(sum(1 for i in range(1, len(c)) if sorted(c)[i] != sorted(c)[i - 1]) + 1)','',22,'Trung vị, hiệu nhỏ nhất, số giá trị khác nhau')))
S.append(S2(c,B+' · 7','Tham lam sau khi sắp xếp: ghép cặp',card('Bài toán',P('n bạn có chiều cao h[i]; ghép thành các cặp sao cho tổng chênh lệch chiều cao của các cặp <b>nhỏ nhất</b>.','Sắp xếp rồi ghép <b>các phần tử kề nhau</b> (1–2, 3–4, …): đây là cách tối ưu.')),CODE('h = [160, 172, 158, 175, 165, 169]\nh.sort()\nt = sum(h[i + 1] - h[i] for i in range(0, len(h), 2))\nprint(h)\nprint(t)',22)+R('h = [160, 172, 158, 175, 165, 169]\nh.sort()\nt = sum(h[i + 1] - h[i] for i in range(0, len(h), 2))\nprint(h)\nprint(t)','',24,'Kết quả')+KEY('Sắp xếp: 158, 160, 165, 169, 172, 175 → (2) + (4) + (3) = <b>9</b>.')))
S.append(SELF(c,B+' · 8','Tự kiểm tra: sau 2 lượt của sắp xếp chọn','Với a = [29, 10, 14, 37, 13], sau đúng 2 lượt (i = 0 và i = 1) của sắp xếp chọn, a bằng gì?','a = [29, 10, 14, 37, 13]\nfor i in range(2):\n    m = i\n    for j in range(i + 1, len(a)):\n        if a[j] < a[m]:\n            m = j\n    a[i], a[m] = a[m], a[i]\nprint(a)',P('Lượt 0: nhỏ nhất 10 (vị trí 1); đổi a[0] ↔ a[1] → [10, 29, 14, 37, 13].','Lượt 1: nhỏ nhất trong [29, 14, 37, 13] là 13 (vị trí 4); đổi a[1] ↔ a[4] → <b>[10, 13, 14, 37, 29]</b>.')+R('a = [29, 10, 14, 37, 13]\nfor i in range(2):\n    m = i\n    for j in range(i + 1, len(a)):\n        if a[j] < a[m]:\n            m = j\n    a[i], a[m] = a[m], a[i]\nprint(a)','',24,'Kết quả thật'),20))
S.append(SELF(c,B+' · 8','Tự kiểm tra: số so sánh nổi bọt','Đếm số phép so sánh của nổi bọt có dừng sớm cho [2, 1, 3, 4, 5, 6].','a = [2, 1, 3, 4, 5, 6]\n# dùng hàm noi_bot ở trên\nprint(noi_bot(a))',P('<b>Lượt 1</b>: j = 0..4 → 5 so sánh; (2,1) đổi chỗ → [1,2,3,4,5,6], doi = True.','<b>Lượt 2</b>: j = 0..3 → 4 so sánh; không đổi → doi = False → <b>dừng</b>.','Tổng: 5 + 4 = <b>9</b>.')+R(BUB+'\nprint(noi_bot([2, 1, 3, 4, 5, 6]))','',24,'Kết quả thật'),20))
S.append(SELF(c,B+' · 8','Tự kiểm tra (HSG): đếm cặp nghịch thế','Cặp (i &lt; j) mà a[i] &gt; a[j] gọi là <b>nghịch thế</b>. Với a = [3, 1, 4, 2], có bao nhiêu? Liên hệ số lần đổi chỗ của sắp xếp nổi bọt/chèn.','a = [3, 1, 4, 2]\nt = sum(1 for i in range(4) for j in range(i + 1, 4) if a[i] > a[j])\nprint(t)',P('Các nghịch thế: (3,1), (3,2), (4,2) → <b>3</b>.','Mỗi lần đổi hai phần tử <b>kề</b> sai thứ tự loại đúng một nghịch thế, nên <b>số lần đổi chỗ của nổi bọt = số nghịch thế</b>; số phần tử dịch của chèn cũng bằng nó.','Mảng ngược hoàn toàn n phần tử có n(n−1)/2 nghịch thế (xấu nhất).')+R('a = [3, 1, 4, 2]\nt = sum(1 for i in range(4) for j in range(i + 1, 4) if a[i] > a[j])\nprint(t)\nb = [3, 1, 4, 2]\nd = 0\nfor i in range(3):\n    for j in range(3 - i):\n        if b[j] > b[j + 1]:\n            b[j], b[j + 1] = b[j + 1], b[j]\n            d += 1\nprint(d)','',22,'Số nghịch thế và số lần đổi của nổi bọt'),20))
S+=END(c,B,['<b>Chọn</b>: mỗi lượt đưa phần tử nhỏ nhất về đầu; so sánh luôn n(n−1)/2; không ổn định.','<b>Nổi bọt</b>: đổi các cặp kề; có <b>cờ dừng sớm</b> nên tốt nhất O(n).','<b>Chèn</b>: giữ phần đầu đã sắp xếp; tốt với mảng gần sắp xếp; ổn định.','Ba thuật toán trên O(n²), bộ nhớ phụ O(1).','<b>Trộn</b> O(n log n) ổn định; <b>đếm phân phối</b> O(n + V).','<b>sort/sorted</b>: Timsort O(n log n), ổn định, có <b>key</b>.'],[('Số nghịch thế','= số lần đổi nổi bọt'),('Ổn định','chèn, nổi bọt, trộn'),('Không ổn định','chọn'),('Nhanh','O(n log n)')],'Quên cờ dừng sớm; nhầm trạng thái sau k lượt; nhầm tính ổn định của chọn.',['Chạy <b>đúng số lượt</b> đề yêu cầu, không chạy hết.','Số so sánh nổi bọt có dừng sớm phụ thuộc dữ liệu.','<code>sorted(..., reverse=True)</code> vẫn giữ tính ổn định.','n = 10⁵ phải dùng <b>sort()</b>, không tự viết O(n²).'],['<b>Sắp xếp nhanh (quicksort)</b>, <b>vun đống (heapsort)</b>.','<b>Radix sort</b>.','<b>Sắp xếp ngoài</b> (dữ liệu lớn hơn RAM).'],
 [('Sắp xếp nào có số phép so sánh luôn n(n−1)/2?',),('Sắp xếp nào ổn định: chọn hay chèn?',),('<code>[3,1,2].sort()</code> trả về?',),('Độ phức tạp của <code>sorted</code>?',),('Mảng đã sắp xếp: nổi bọt có dừng sớm làm mấy so sánh (n phần tử)?',)],
 [('<b>Chọn</b>.',),('<b>Chèn</b>.',),('<b>None</b>.',),('<b>O(n log n)</b>.',),('<b>n − 1</b>.',)],
 [('Mức 1. Sắp xếp giảm dần danh sách không dùng sort. Thử [4, 9, 2, 7].',),('Mức 1. In danh sách sau từng lượt của sắp xếp chèn cho [5, 2, 4, 6, 1, 3].',),('Mức 2. Đếm số lần đổi chỗ của sắp xếp nổi bọt cho [5, 1, 4, 2, 8].',),('Mức 2. Sắp xếp học sinh theo điểm giảm dần, bằng điểm theo tên tăng dần. Thử [("An",8),("Binh",9),("Chi",8)].',),('Mức 3 (HSG). Đếm số cặp nghịch thế của dãy n = 10⁵ bằng sắp xếp trộn trong O(n log n) (sửa bước trộn).',),('Mức 3 (HSG). Cho n đoạn [l, r]; hợp các đoạn chồng nhau và in tổng độ dài phần được phủ. Thử [(1,3),(2,6),(8,10),(15,18)].',)],
 [(V('a=[4,9,2,7]\nfor i in range(len(a)):\n    for j in range(i+1,len(a)):\n        if a[j]>a[i]: a[i],a[j]=a[j],a[i]\nprint(a)')+'.',),('Đặt <code>print(a)</code> ở cuối mỗi lượt i của vòng for ngoài.',),(V('b=[5,1,4,2,8]\nd=0\nfor i in range(4):\n    for j in range(4-i):\n        if b[j]>b[j+1]:\n            b[j],b[j+1]=b[j+1],b[j];d+=1\nprint(d)')+' lần (= số nghịch thế).',),('<code>sorted(hs, key=lambda p: (-p[1], p[0]))</code> → '+V('hs=[("An",8),("Binh",9),("Chi",8)]\nprint(sorted(hs,key=lambda p:(-p[1],p[0])))')+'.',),('Khi lấy phần tử từ nửa phải trước phần tử còn lại nửa trái, cộng thêm <b>số phần tử còn lại của nửa trái</b> vào đáp án.',),('Sắp xếp theo l; duyệt, gộp nếu l ≤ r hiện tại → '+V('d=sorted([(1,3),(2,6),(8,10),(15,18)])\nt=0;cl,cr=d[0]\nfor l,r in d[1:]:\n    if l<=cr: cr=max(cr,r)\n    else: t+=cr-cl;cl,cr=l,r\nt+=cr-cl\nprint(t)')+'.',)],hper=2)
